class Rectangle:
    def __init__(self, width, height):
        self._width = width
        self._height = height

    @property
    def width(self):
        return self._width

    @width.setter
    def width(self, value):
        self._width = value

    @property
    def height(self):
        return self._height

    @height.setter
    def height(self, value):
        self._height = value

    def area(self):
        return self._width * self._height


class Square(Rectangle):
    '''Viola LSP: fuerza width == height, rompiendo el contrato de Rectangle'''

    @property
    def width(self):
        return self._width

    @width.setter
    def width(self, value):
        # Viola LSP: cambia height cuando se cambia width
        self._width = value
        self._height = value

    @property
    def height(self):
        return self._height

    @height.setter
    def height(self, value):
        # Viola LSP: cambia width cuando se cambia height
        self._width = value
        self._height = value


# Test que funciona con Rectangle pero FALLA con Square
def test_rectangle_behavior(rect: Rectangle):
    '''Test que espera comportamiento de Rectangle'''
    rect.width = 5
    rect.height = 10

    # Espera: area = 5 * 10 = 50
    # Con Rectangle: funciona (5 * 10 = 50)
    # Con Square: FALLA (height setter cambió width a 10, area = 10 * 10 = 100)
    assert rect.area() == 50, f'Expected 50, got {rect.area()}'


