from abc import ABC, abstractmethod

# Solución 1: jerarquía separada (Square no hereda de Rectangle)
class Shape(ABC):
    @abstractmethod
    def area(self) -> float:
        pass

class Rectangle(Shape):
    def __init__(self, width, height):
        self._width = width
        self._height = height

    @property
    def width(self):
        return self._width

    @width.setter
    def width(self, value):
        self._width = value

    @property
    def height(self):
        return self._height

    @height.setter
    def height(self, value):
        self._height = value

    def area(self):
        return self._width * self._height

class Square(Shape):
    '''Square tiene su propia invariante: side == side'''

    def __init__(self, side):
        self._side = side

    @property
    def side(self):
        return self._side

    @side.setter
    def side(self, value):
        self._side = value

    def area(self):
        return self._side ** 2

# Test que funciona con CUALQUIER Shape
def test_shape_area(shape: Shape, expected_area: float):
    assert shape.area() == expected_area, f'Expected {expected_area}, got {shape.area()}'

# Uso:
test_shape_area(Rectangle(5, 10), 50)  # ✓ Pasa
test_shape_area(Square(5), 25)         # ✓ Pasa

# LSP cumplido: cada subclase respeta el contrato de Shape
# Rectangle y Square son sustituibles por Shape sin romper comportamiento


# Solución 2: diseño por contrato (precondiciones/postcondiciones)
class RectangleWithContract(ABC):
    '''Contrato: width y height son independientes'''

    @abstractmethod
    def get_width(self) -> float:
        pass

    @abstractmethod
    def set_width(self, value: float):
        pass

    @abstractmethod
    def get_height(self) -> float:
        pass

    @abstractmethod
    def set_height(self, value: float):
        pass

    def area(self) -> float:
        return self.get_width() * self.get_height()


class MutableRectangle(RectangleWithContract):
    '''Cumple el contrato: width y height independientes'''

    def __init__(self, width, height):
        self._width = width
        self._height = height

    def get_width(self):
        return self._width

    def set_width(self, value):
        self._width = value

    def get_height(self):
        return self._height

    def set_height(self, value):
        self._height = value


class ImmutableRectangle(RectangleWithContract):
    '''Cumple el contrato: width y height independientes (inmutables)'''

    def __init__(self, width, height):
        self._width = width
        self._height = height

    def get_width(self):
        return self._width

    def set_width(self, value):
        # Inmutabilidad: crea nuevo objeto en vez de modificar
        return ImmutableRectangle(value, self._height)

    def get_height(self):
        return self._height

    def set_height(self, value):
        return ImmutableRectangle(self._width, value)

# Ambas subclases son sustituibles por RectangleWithContract
# LSP cumplido: el contrato se respeta en ambas

