class Shape:
    def __init__(self):
        self._dimensions = {}

    def set_dimension(self, name, value):
        self._dimensions[name] = value

    def get_dimension(self, name):
        return self._dimensions.get(name, 0)

    def area(self):
        raise NotImplementedError


class Circle(Shape):
    '''Viola LSP: fuerza radius == diameter/2'''

    def set_dimension(self, name, value):
        # Viola LSP: cambiar radius también cambia diameter
        if name == 'radius':
            self._dimensions['radius'] = value
            self._dimensions['diameter'] = value * 2  # ← fuerza invariante
        elif name == 'diameter':
            self._dimensions['diameter'] = value
            self._dimensions['radius'] = value / 2  # ← fuerza invariante
        else:
            super().set_dimension(name, value)

    def area(self):
        return math.pi * self._dimensions['radius'] ** 2


def test_shape_dimension_independence(shape: Shape):
    '''Test que espera que puedas cambiar dimensiones independientemente'''
    shape.set_dimension('radius', 5)
    shape.set_dimension('diameter', 20)

    # Espera: radius = 5, diameter = 20 (independientes)
    # Con Circle: FALLA (set_dimension('diameter', 20) cambió radius a 10)
    assert shape.get_dimension('radius') == 5, f"Expected radius=5, got {shape.get_dimension('radius')}"
    assert shape.get_dimension('diameter') == 20, f"Expected diameter=20, got {shape.get_dimension('diameter')}"


