class BirdBase(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def make_sound(self):
        pass


class FlyingBird(BirdBase):
    def fly(self):
        return f'{self.name} is flying'

    def make_sound(self):
        return 'Chirp'


class SwimmingBird(BirdBase):
    def swim(self):
        return f'{self.name} is swimming'

    def make_sound(self):
        return 'Honk'


class SparrowFixed(FlyingBird):
    pass


class PenguinFixed(SwimmingBird):
    pass


print('--- Jerarquía correcta (separar comportamientos) ---')

def test_bird_makes_sound(bird: BirdBase):
    sound = bird.make_sound()
    print(f'  {bird.name} says: {sound}')
    return bool(sound)


def test_flying_bird_can_fly(bird: FlyingBird):
    result = bird.fly()
    print(f'  {result}')
    return 'flying' in result


